// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DAO} from "../src/DAO.sol";

contract InvMutTest is Test {
    DAO c;

    function setUp() public {
        c = new DAO();
    }

    function testFuzz_property(address recipient, uint256 amount, address actor) public {
        vm.assume(recipient != address(0));
        vm.assume(actor != address(0));
        vm.prank(actor);
        c.newGrantProposal(recipient, amount);
        // Every grant proposal must advance the proposal counter by exactly one.
        assertTrue(c.proposalCount() == 1);
    }
}
